    }

    button:hover {
      background: var(--primary-hover);
      transform: translateY(-1px);
    }

    button:focus-visible {
      outline: 3px solid transparent;
      box-shadow: 0 0 0 4px #ffffff, 0 0 0 7px var(--focus);
    }

    @media (prefers-reduced-motion: reduce) {
