</head>
<body>
  <a class="skip-link" href="#main-content">Skip to main content</a>

  <main id="main-content">
    <section class="card" aria-labelledby="page-title">
      <p class="eyebrow">Preferences</p>
      <h1 id="page-title">Choose your notification channel</h1>
      <p class="intro">Tell us the best way to keep you updated about product activity and account changes.</p>

      <form id="notification-form" novalidate>
        <div class="form-field">
          <fieldset aria-describedby="notification-hint notification-error">
            <legend>
              How do you prefer to receive notifications?
              <span class="required" aria-hidden="true">*</span>
            </legend>
            <p id="notification-hint" class="hint">Choose one option.</p>

            <div class="radio-group">
              <label class="radio-option" for="notification-email">
                <input type="radio" id="notification-email" name="notificationPreference" value="Email" required>
                <span class="option-text">Email</span>
              </label>

              <label class="radio-option" for="notification-sms">
                <input type="radio" id="notification-sms" name="notificationPreference" value="SMS" required>
                <span class="option-text">SMS</span>
              </label>

              <label class="radio-option" for="notification-push">
                <input type="radio" id="notification-push" name="notificationPreference" value="Push Notifications" required>
                <span class="option-text">Push Notifications</span>
              </label>
            </div>
          </fieldset>

          <p id="notification-error" class="error-message" aria-live="polite"></p>
        </div>

        <button type="submit">Submit</button>
        <p id="form-status" class="success-message" aria-live="polite"></p>
      </form>
    </section>
  </main>

  <script>
    const form = document.querySelector("#notification-form");
    const radios = [...document.querySelectorAll('input[name="notificationPreference"]')];
    const errorMessage = document.querySelector("#notification-error");
    const statusMessage = document.querySelector("#form-status");

    function setInvalid(isInvalid) {
      radios.forEach((radio) => {
        radio.setAttribute("aria-invalid", String(isInvalid));
      });
    }

    radios.forEach((radio) => {
      radio.addEventListener("change", () => {
        setInvalid(false);
        errorMessage.textContent = "";
        statusMessage.textContent = "";
      });
    });

    form.addEventListener("submit", (event) => {
      event.preventDefault();

      const selected = radios.find((radio) => radio.checked);

      if (!selected) {
        setInvalid(true);
        errorMessage.textContent = "Choose how you prefer to receive notifications.";
        statusMessage.textContent = "";
        radios[0].focus();
        return;
      }

      setInvalid(false);
      errorMessage.textContent = "";
      statusMessage.textContent = `Saved preference: ${selected.value}.`;
    });
  </script>
